package com.mavric.health.persistence.sqlserver;
import java.util.*;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import org.springframework.security.core.context.SecurityContextHolder;
import com.mavric.health.identity.Actor;
import com.mavric.health.tenancy.TenantRef;
import com.mavric.health.audit.TraceContext;
import com.mavric.health.shared.ApiException;
import com.mavric.health.persistence.sqlserver.SqlServerIdentityStoreTest.ModelTransactionManager;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Resource contracts and modeled executor/manager; no SQL engine, clinical certification or real permissions. */
class SqlServerPlatformStoreTest {
 static final String ID="aa000000-0000-4000-8000-000000000001",OTHER="bb000000-0000-4000-8000-000000000001",TIME="2026-11-04T00:00:00.123456Z";
 final SqlServerExecutor executor=mock(SqlServerExecutor.class);final ModelTransactionManager manager=new ModelTransactionManager();final SqlServerPlatformStore store=new SqlServerPlatformStore(executor,manager);final MockHttpServletRequest request=new MockHttpServletRequest("GET","/api/platform/plans");final Deque<SqlServerExecutor.Result> results=new ArrayDeque<>();final List<SqlServerProcedure> calls=new ArrayList<>();final List<List<Object>> args=new ArrayList<>();
 SqlServerPlatformStoreTest(){actor("SAD");when(executor.execute(any(),any(),any(Object[].class))).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());var c=inv.<SqlServerContext>getArgument(1);assertEquals(SqlServerContext.Scope.REQUEST,c.scope());assertEquals(ID,c.actorId());assertNull(c.tenantId());assertEquals("a".repeat(64),c.tokenHash());calls.add(inv.getArgument(0));args.add(Arrays.asList(((Object[])inv.getRawArguments()[2]).clone()));return results.removeFirst();});}
 void actor(String role){request.setAttribute("health.actor",new Actor(ID,"Synthetic","qa@example.test",null,List.of(role),"a".repeat(64)));request.removeAttribute("health.tenant");}
 static Map<String,Object> plan(){var r=new LinkedHashMap<String,Object>();r.put("id",ID);r.put("planId",ID);r.put("name","Synthetic clinic");r.put("description","");r.put("status","PUBLISHED");r.put("currentVersion",1);r.put("version",1);r.put("baseMinor",1000000000000L);r.put("branchMinor",0L);r.put("professionalMinor",0L);for(String suffix:List.of("Branches","Professionals","Specialties")){r.put("included"+suffix,1);r.put("max"+suffix,10);}r.put("annualDiscount",60);r.put("kinds",List.of("CLINIC"));r.put("domains",List.of("HUMAN"));r.put("modules",List.of("CORE","PORTAL"));r.put("createdAt",TIME);return r;}
 static Map<String,Object> user(){var r=new LinkedHashMap<String,Object>();r.put("id",ID);r.put("name","Synthetic");r.put("email","qa@example.test");r.put("clinicalDomain",null);r.put("credential",null);r.put("active",true);return r;}
 static Map<String,Object> audit(){var r=new LinkedHashMap<String,Object>();r.put("id",Long.MAX_VALUE);r.put("tenantId",null);r.put("actorId",null);r.put("action","TENANT_CREATED");r.put("targetId","opaque");r.put("metadata",null);r.put("createdAt",TIME);return r;}
 static Map<String,Object> realSpecialty() throws Exception {String sql;try(var in=SqlServerPlatformStoreTest.class.getResourceAsStream("/db/sqlserver/V2__catalog_seed.sql")){sql=new String(in.readAllBytes(),StandardCharsets.UTF_8);}String line=sql.lines().filter(s->s.startsWith("INSERT INTO dbo.specialties")).max(Comparator.comparingInt(String::length)).orElseThrow();StringBuilder json=new StringBuilder();var matcher=java.util.regex.Pattern.compile("N'((?:''|[^'])*)'").matcher(line.substring(line.indexOf("CAST(N'")));while(matcher.find())json.append(matcher.group(1).replace("''","'"));assertTrue(json.length()>4000);var profile=new tools.jackson.databind.ObjectMapper().readValue(json.toString(),Map.class);var out=new LinkedHashMap<String,Object>();out.put("code",profile.get("code"));out.put("name",profile.get("name"));out.put("domain",profile.get("patientDomain"));out.put("dental",line.substring(0,line.indexOf("CAST(N'")).endsWith(",1,"));out.put("profile",profile);return out;}
 void rows(List<Map<String,Object>> rows){results.add(new SqlServerExecutor.Result(List.of(rows),List.of(0)));}
 @AfterEach void cleanup(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 static void safe(Runnable work){var e=assertThrows(ApiException.class,work::run);assertEquals(500,e.status);assertEquals("DATABASE_ERROR",e.code);assertNull(e.getCause());}
 @Test void exactFourDescriptorsNullPositionalArgsClampingAndQueryBound(){rows(List.of(plan()));store.plans(request);rows(List.of(user()));store.users(request,0);rows(List.of());store.specialties(request,null);rows(List.of());store.audit(request,999);assertEquals(List.of(SqlServerProcedure.PLATFORM_PLANS,SqlServerProcedure.PLATFORM_USERS,SqlServerProcedure.PLATFORM_SPECIALTIES,SqlServerProcedure.PLATFORM_AUDIT),calls);assertEquals(Arrays.asList((Object)null),args.getFirst());assertEquals(Arrays.asList(null,1),args.get(1));assertEquals(List.of(""),args.get(2));assertEquals(List.of(200),args.getLast());rows(List.of());store.specialties(request,"x".repeat(220));assertEquals(220,((String)args.getLast().getFirst()).length());assertEquals(400,assertThrows(ApiException.class,()->store.specialties(request,"x".repeat(221))).status);assertEquals(5,calls.size());}
 @Test void projectionsPlan21User6Specialty5Audit7AndRealProfileDeepImmutable() throws Exception {var p=plan();p.put("passwordHash","private");rows(List.of(p));var plans=store.plans(request);assertEquals(21,plans.getFirst().size());assertFalse(plans.toString().contains("private"));assertThrows(UnsupportedOperationException.class,plans::clear);assertThrows(UnsupportedOperationException.class,((List<?>)plans.getFirst().get("modules"))::clear);var u=user();u.put("platformRole","private");rows(List.of(u));var users=store.users(request,1);assertEquals(6,users.getFirst().size());assertTrue(users.getFirst().containsKey("clinicalDomain"));assertNull(users.getFirst().get("clinicalDomain"));var specialty=realSpecialty();rows(List.of(specialty));var mapped=store.specialties(request,"%").getFirst();assertEquals(5,mapped.size());assertEquals(specialty.get("profile"),mapped.get("profile"));var profile=(Map<?,?>)mapped.get("profile");assertThrows(UnsupportedOperationException.class,profile::clear);assertThrows(UnsupportedOperationException.class,((List<?>)profile.get("fields"))::clear);rows(List.of(audit()));assertEquals(7,store.audit(request,1).getFirst().size());}
 @Test void plansCanonicalVersionsQuotasAndDoctorOneWithoutClamping(){var p=plan();p.put("kinds",List.of("DOCTOR"));rows(List.of(p));assertEquals(1,store.plans(request).getFirst().get("includedProfessionals"));for(var replacement:List.of(Map.entry("planId",OTHER),Map.entry("currentVersion",2),Map.entry("baseMinor",1),Map.entry("maxBranches",0),Map.entry("annualDiscount",61),Map.entry("modules",List.of("PORTAL")),Map.entry("status","bad"),Map.entry("version",1L))){p=plan();p.put(replacement.getKey(),replacement.getValue());rows(List.of(p));safe(()->store.plans(request));}p=plan();p.put("kinds",List.of("DOCTOR"));p.put("includedProfessionals",4);rows(List.of(p));safe(()->store.plans(request));}
 @Test void everyPlanColumnRequiredAndNoInventedPaging(){for(String key:plan().keySet()){var p=plan();p.remove(key);rows(List.of(p));safe(()->store.plans(request));}var many=new ArrayList<Map<String,Object>>();for(int i=0;i<250;i++)many.add(plan());rows(many);assertEquals(250,store.plans(request).size());}
 @Test void auditArbitraryJsonNullDecimalAndCycles(){var data=new LinkedHashMap<String,Object>();var nested=new ArrayList<>(Arrays.asList(null,new BigDecimal("99999999999999999999.123456"),false));data.put("values",nested);var a=audit();a.put("metadata",data);rows(List.of(a));var out=store.audit(request,1).getFirst();var metadata=(Map<?,?>)out.get("metadata");var values=(List<?>)metadata.get("values");assertNull(values.getFirst());assertEquals(nested.get(1),values.get(1));assertThrows(UnsupportedOperationException.class,values::clear);nested.clear();assertEquals(3,values.size());var cycle=new ArrayList<>();cycle.add(cycle);for(Object invalid:List.of(cycle,Double.NaN,Map.of(1,"bad"))){a=audit();a.put("metadata",invalid);rows(List.of(a));safe(()->store.audit(request,1));}a=audit();a.put("action","CLINICAL_READ");rows(List.of(a));safe(()->store.audit(request,1));}
 @Test void invalidRowsResultsetsTimestampsAndLimitsRollback(){var p=plan();p.put("createdAt","2026-11-04T00:00:00.123456789Z");rows(List.of(p));safe(()->store.plans(request));var u=user();u.put("active",1);rows(List.of(u));safe(()->store.users(request,1));rows(List.of(user(),user()));safe(()->store.users(request,1));results.add(new SqlServerExecutor.Result(List.of(),List.of()));safe(()->store.plans(request));results.add(new SqlServerExecutor.Result(List.of(List.of(),List.of()),List.of()));safe(()->store.plans(request));}
 @Test void directAuthorizationAndNoHttpAuthorityBeforeExecutor(){actor("SOP");assertEquals(403,assertThrows(ApiException.class,()->store.plans(request)).status);actor("SAD");request.setAttribute("health.tenant",new TenantRef(ID,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of()));assertEquals(403,assertThrows(ApiException.class,()->store.plans(request)).status);request.setAttribute("health.tenant","bad");safe(()->store.plans(request));safe(()->store.plans(null));verifyNoInteractions(executor);}
 @Test void requiredJoinCommitAndVendorErrorsNoRetry(){rows(List.of(plan()));assertThrows(RuntimeException.class,()->manager.outer(()->{store.plans(request);assertEquals(List.of("begin:0"),manager.events);throw new RuntimeException("synthetic cancel");}));assertEquals("rollback",manager.events.getLast());rows(List.of(plan()));manager.failCommit=true;safe(()->store.plans(request));doThrow(new RuntimeException(new java.sql.SQLException("private driver",null,51001))).when(executor).execute(any(),any(),any(Object[].class));var error=assertThrows(ApiException.class,()->store.users(request,1));assertEquals(403,error.status);assertFalse(error.toString().contains("private"));verify(executor,times(3)).execute(any(),any(),any(Object[].class));}
 @Test void userSpecialtyAndAuditColumnsRequiredAndNullableTypesExact() throws Exception {for(String key:user().keySet()){var row=user();row.remove(key);rows(List.of(row));safe(()->store.users(request,1));}var specialty=realSpecialty();for(String key:specialty.keySet()){var row=new LinkedHashMap<>(specialty);row.remove(key);rows(List.of(row));safe(()->store.specialties(request,""));}for(String key:audit().keySet()){var row=audit();row.remove(key);rows(List.of(row));safe(()->store.audit(request,1));}var bad=user();bad.put("credential",1);rows(List.of(bad));safe(()->store.users(request,1));var badSpecialty=new LinkedHashMap<>(specialty);badSpecialty.put("profile","not object");rows(List.of(badSpecialty));safe(()->store.specialties(request,""));}
 @Test void auditScalarNullJsonAndSpecialtiesHaveNoInventedLimit() throws Exception {for(Object value:Arrays.asList(null,true,"text",new BigDecimal("123.456"),Arrays.asList(null,"item"))){var row=audit();row.put("metadata",value);rows(List.of(row));assertEquals(value,store.audit(request,1).getFirst().get("metadata"));}var specialty=realSpecialty();rows(Collections.nCopies(250,specialty));assertEquals(250,store.specialties(request,"%").size());rows(Collections.nCopies(201,user()));safe(()->store.users(request,200));rows(Collections.nCopies(201,audit()));safe(()->store.audit(request,200));}
 @Test void malformedActorUuidTokenAndMissingActorDoNotReachExecutor(){request.setAttribute("health.actor",new Actor("bad","Synthetic","qa@example.test",null,List.of("SAD"),"a".repeat(64)));safe(()->store.plans(request));request.setAttribute("health.actor",new Actor(ID,"Synthetic","qa@example.test",null,List.of("SAD"),"bad"));safe(()->store.plans(request));request.removeAttribute("health.actor");assertEquals(403,assertThrows(ApiException.class,()->store.plans(request)).status);verifyNoInteractions(executor);}


 static Map<String,Object> tenantRow(){var r=new LinkedHashMap<String,Object>();for(String k:List.of("id","ownerUserId","planId"))r.put(k,ID);for(String k:List.of("name","ownerName","ownerEmail","planName"))r.put(k,"Synthetic ???");r.put("slug","synthetic-clinic");r.put("kind","CLINIC");r.put("domain","HUMAN");r.put("status","SUSPENDED");r.put("timezone","America/Lima");r.put("createdAt",TIME);r.put("renewalDate","2028-02-29");r.put("cycle","YEARLY");for(String k:List.of("planVersion","branchQuota","professionalQuota","specialtyQuota","includedBranches","includedProfessionals"))r.put(k,1);r.put("annualDiscount",60);for(String k:List.of("baseMinor","branchMinor","professionalMinor","branchesUsed","professionalsUsed","specialtiesUsed"))r.put(k,Long.MAX_VALUE);r.put("modules",new ArrayList<>(List.of("CORE","PORTAL")));return r;}
 @Test void tenantThreeOperationsExactBindsProjectionAndHistoricalUsage(){var row=tenantRow();row.put("private","canary");rows(List.of(row));var list=store.tenants(request,999);assertEquals(29,list.getFirst().size());assertEquals(Long.MAX_VALUE,list.getFirst().get("professionalsUsed"));assertEquals("SUSPENDED",list.getFirst().get("status"));assertFalse(list.toString().contains("canary"));assertThrows(UnsupportedOperationException.class,list::clear);assertThrows(UnsupportedOperationException.class,((List<?>)list.getFirst().get("modules"))::clear);((List<?>)row.get("modules")).clear();assertEquals(List.of("CORE","PORTAL"),list.getFirst().get("modules"));rows(List.of(tenantRow()));assertEquals(ID,store.tenant(request,ID).get("id"));rows(List.of(tenantRow()));assertEquals(29,store.status(request,ID,"SUSPENDED"," reason ",r->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());assertThrows(UnsupportedOperationException.class,r::clear);return r;}).size());assertEquals(List.of(SqlServerProcedure.PLATFORM_TENANTS,SqlServerProcedure.PLATFORM_TENANTS,SqlServerProcedure.SAAS_TENANT_STATUS),calls);assertEquals(Arrays.asList(null,200),args.get(0));assertEquals(List.of(ID,1),args.get(1));assertEquals(List.of(ID,"SUSPENDED"," reason "),args.get(2));rows(List.of());assertEquals(List.of(),store.tenants(request,0));assertEquals(Arrays.asList(null,1),args.getLast());}
 @Test void everyTenantColumnRequiredAndExactTypedDomainDateContract(){for(String k:tenantRow().keySet()){var r=tenantRow();r.remove(k);rows(List.of(r));safe(()->store.tenant(request,ID));assertEquals("rollback",manager.events.getLast());}for(var bad:List.of(Map.entry("id",OTHER),Map.entry("ownerUserId","bad"),Map.entry("renewalDate","2027-02-29"),Map.entry("renewalDate","2028-2-29"),Map.entry("createdAt","2026-11-04T00:00:00.123456789Z"),Map.entry("timezone","Invalid/Zone"),Map.entry("slug","admin"),Map.entry("kind","bad"),Map.entry("domain","ANIMAL"),Map.entry("status","bad"),Map.entry("cycle","bad"),Map.entry("planVersion",1L),Map.entry("branchQuota",0),Map.entry("annualDiscount",61),Map.entry("baseMinor",1),Map.entry("branchesUsed",-1L),Map.entry("modules",List.of("PORTAL")))){var r=tenantRow();r.put(bad.getKey(),bad.getValue());rows(List.of(r));safe(()->store.tenant(request,ID));}var historical=tenantRow();historical.put("kind","DOCTOR");historical.put("professionalQuota",4);rows(List.of(historical));assertEquals(4,store.tenant(request,ID).get("professionalQuota"));}
 @Test void tenantCardinalityMissingMismatchAndStatusNeverQueriesAgain(){rows(List.of());assertEquals(404,assertThrows(ApiException.class,()->store.tenant(request,ID)).status);rows(List.of(tenantRow(),tenantRow()));safe(()->store.tenant(request,ID));rows(List.of());safe(()->store.status(request,ID,"ACTIVE","why",r->r));var r=tenantRow();r.put("id",OTHER);rows(List.of(r));safe(()->store.status(request,ID,"ACTIVE","why",v->v));results.add(new SqlServerExecutor.Result(List.of(),List.of()));safe(()->store.tenants(request,1));results.add(new SqlServerExecutor.Result(List.of(List.of(),List.of()),List.of()));safe(()->store.tenants(request,1));rows(Collections.nCopies(2,tenantRow()));safe(()->store.tenants(request,1));assertEquals(2,Collections.frequency(calls,SqlServerProcedure.SAAS_TENANT_STATUS));}
 @Test void statusInputsAndAuthorityRejectBeforeExecutor(){for(String value:Arrays.asList(null,"active","BAD"))assertEquals(400,assertThrows(ApiException.class,()->store.status(request,ID,value,"why",r->r)).status);for(String reason:Arrays.asList(null," ","x".repeat(501)))assertEquals(400,assertThrows(ApiException.class,()->store.status(request,ID,"ACTIVE",reason,r->r)).status);assertEquals(400,assertThrows(ApiException.class,()->store.tenant(request,"bad")).status);actor("SOP");assertEquals(403,assertThrows(ApiException.class,()->store.tenants(request,1)).status);assertEquals(403,assertThrows(ApiException.class,()->store.status(request,ID,"ACTIVE","why",r->r)).status);verifyNoInteractions(executor);}
 @Test void statusCallbackMappingCommitOuterRollbackAndVendorFailures(){rows(List.of(tenantRow()));safe(()->store.status(request,ID,"ACTIVE","why",r->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());throw new IllegalStateException("private callback");}));assertEquals("rollback",manager.events.getLast());rows(List.of(tenantRow()));manager.failCommit=true;safe(()->store.status(request,ID,"ACTIVE","why",r->r));rows(List.of(tenantRow()));assertThrows(RuntimeException.class,()->manager.outer(()->{store.status(request,ID,"ACTIVE","why",r->r);throw new RuntimeException("cancel");}));assertEquals("rollback",manager.events.getLast());for(int code:List.of(51000,51001,51002,51003)){doThrow(new RuntimeException(new java.sql.SQLException("private driver",null,code))).when(executor).execute(any(),any(),any(Object[].class));var e=assertThrows(ApiException.class,()->store.status(request,ID,"ACTIVE","why",r->r));assertEquals(Map.of(51000,400,51001,403,51002,404,51003,409).get(code),e.status);assertFalse(e.toString().contains("private"));}verify(executor,times(7)).execute(any(),any(),any(Object[].class));}

 @Test void nullTenantFieldsWrongScalarTypesAndStatusResultSetsFailClosed(){for(String key:tenantRow().keySet()){var r=tenantRow();r.put(key,null);rows(List.of(r));safe(()->store.tenant(request,ID));}for(var replacement:List.of(Map.entry("name",true),Map.entry("renewalDate",java.time.LocalDate.of(2028,2,29)),Map.entry("professionalQuota",1L),Map.entry("professionalMinor",1.0),Map.entry("specialtiesUsed",1),Map.entry("modules",List.of("CORE",1)))){var r=tenantRow();r.put(replacement.getKey(),replacement.getValue());rows(List.of(r));safe(()->store.tenant(request,ID));}results.add(new SqlServerExecutor.Result(List.of(List.of(tenantRow()),List.of()),List.of()));safe(()->store.status(request,ID,"ACTIVE","why",r->r));rows(List.of(tenantRow(),tenantRow()));safe(()->store.status(request,ID,"ACTIVE","why",r->r));}
 @Test void allStatusValuesAndReasonBoundaryArePreservedWithoutTrimming(){String reason=" "+"?".repeat(498)+" ";for(String status:List.of("TRIAL","ACTIVE","SUSPENDED","CANCELLED")){rows(List.of(tenantRow()));store.status(request,ID,status,reason,r->r);assertEquals(List.of(ID,status,reason),args.getLast());}assertEquals(4,calls.size());assertTrue(calls.stream().allMatch(p->p==SqlServerProcedure.SAAS_TENANT_STATUS));}
}
